-- mod-retail-pets: companion pets and mounts with retail models. Generated by tools/build_pets.py from
-- data/pets.tsv: change that file and run the tool again, don't edit this one.
-- The client needs the module's two patches (see the README), or it shows nothing at all.

-- The pets and the mounts' creatures, and the form looks' preview creatures.
DELETE FROM `creature` WHERE `guid` IN (9502090);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (9502000, 9502001, 9502002, 9502003, 9502004, 9502005, 9502006, 9502007, 9502008, 9502009, 9502010, 9502011, 9502012, 9502013, 9502014, 9502015, 9502017, 9502018, 9502019, 9502020, 9502021, 9502022, 9502016, 9502090);
