DELETE FROM `gossip_menu_option` WHERE `MenuID` IN (9502090);
DELETE FROM `gossip_menu` WHERE `MenuID` IN (9502090);
DELETE FROM `npc_text` WHERE `ID` IN (9502090, 9502091);

